Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase,System.Xaml,System.Web.Extensions
function New-HcCheckerPngBytes{$width=8;$height=8;$stride=$width*4;$pixels=New-Object byte[] ($stride*$height);for($y=0;$y-lt$height;$y++){for($x=0;$x-lt$width;$x++){$o=($y*$stride)+($x*4);if($x-lt4){$pixels[$o]=24;$pixels[$o+1]=32;$pixels[$o+2]=238}else{$pixels[$o]=238;$pixels[$o+1]=48;$pixels[$o+2]=30};$pixels[$o+3]=255}};$bitmap=[Windows.Media.Imaging.BitmapSource]::Create($width,$height,96,96,[Windows.Media.PixelFormats]::Bgra32,$null,$pixels,$stride);$encoder=New-Object Windows.Media.Imaging.PngBitmapEncoder;$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($bitmap));$stream=New-Object IO.MemoryStream;try{$encoder.Save($stream);return ,([byte[]]$stream.ToArray())}finally{$stream.Dispose()}}
function New-HcTexturedProbeGlb([string]$Path){$png=New-HcCheckerPngBytes;$ms=New-Object IO.MemoryStream;$bw=New-Object IO.BinaryWriter($ms);try{foreach($f in @([single]-1,[single]-1,[single]0,[single]1,[single]-1,[single]0,[single]1,[single]1,[single]0,[single]-1,[single]1,[single]0)){$bw.Write($f)};foreach($i in 0..3){$bw.Write([single]0);$bw.Write([single]0);$bw.Write([single]1)};foreach($f in @([single]0,[single]0,[single]1,[single]0,[single]1,[single]1,[single]0,[single]1)){$bw.Write($f)};foreach($ix in @([uint16]0,[uint16]1,[uint16]2,[uint16]0,[uint16]2,[uint16]3)){$bw.Write($ix)};$imageOffset=[int]$ms.Position;$bw.Write($png);while(($ms.Position%4)-ne0){$bw.Write([byte]0)};$bw.Flush();$bin=[byte[]]$ms.ToArray()}finally{$bw.Dispose();$ms.Dispose()};$json="{`"asset`":{`"version`":`"2.0`"},`"scene`":0,`"scenes`":[{`"nodes`":[0]}],`"nodes`":[{`"mesh`":0}],`"meshes`":[{`"primitives`":[{`"attributes`":{`"POSITION`":0,`"NORMAL`":1,`"TEXCOORD_0`":2},`"indices`":3,`"material`":0,`"mode`":4}]}],`"materials`":[{`"doubleSided`":true,`"pbrMetallicRoughness`":{`"baseColorFactor`":[1,1,1,1],`"baseColorTexture`":{`"index`":0,`"texCoord`":0},`"metallicFactor`":0,`"roughnessFactor`":1}}],`"textures`":[{`"source`":0}],`"images`":[{`"bufferView`":4,`"mimeType`":`"image/png`"}],`"buffers`":[{`"byteLength`":$($bin.Length)}],`"bufferViews`":[{`"buffer`":0,`"byteOffset`":0,`"byteLength`":48},{`"buffer`":0,`"byteOffset`":48,`"byteLength`":48},{`"buffer`":0,`"byteOffset`":96,`"byteLength`":32},{`"buffer`":0,`"byteOffset`":128,`"byteLength`":12},{`"buffer`":0,`"byteOffset`":$imageOffset,`"byteLength`":$($png.Length)}],`"accessors`":[{`"bufferView`":0,`"componentType`":5126,`"count`":4,`"type`":`"VEC3`",`"min`":[-1,-1,0],`"max`":[1,1,0]},{`"bufferView`":1,`"componentType`":5126,`"count`":4,`"type`":`"VEC3`"},{`"bufferView`":2,`"componentType`":5126,`"count`":4,`"type`":`"VEC2`"},{`"bufferView`":3,`"componentType`":5123,`"count`":6,`"type`":`"SCALAR`",`"min`":[0],`"max`":[3]}]}";$jb=[Text.Encoding]::UTF8.GetBytes($json);$jp=(4-($jb.Length%4))%4;$jc=New-Object byte[] ($jb.Length+$jp);[Array]::Copy($jb,$jc,$jb.Length);for($i=$jb.Length;$i-lt$jc.Length;$i++){$jc[$i]=0x20};$total=12+8+$jc.Length+8+$bin.Length;$fs=[IO.File]::Create($Path);$out=New-Object IO.BinaryWriter($fs);try{$out.Write([byte[]](0x67,0x6C,0x54,0x46));$out.Write([uint32]2);$out.Write([uint32]$total);$out.Write([uint32]$jc.Length);$out.Write([uint32]0x4E4F534A);$out.Write($jc);$out.Write([uint32]$bin.Length);$out.Write([uint32]0x004E4942);$out.Write($bin)}finally{$out.Dispose();$fs.Dispose()}}
function Get-HcStagedRenderStats($View,[string]$Label){$width=220;$height=180;$View.Width=$width;$View.Height=$height;$View.Measure((New-Object Windows.Size($width,$height)));$View.Arrange((New-Object Windows.Rect(0,0,$width,$height)));$View.UpdateLayout();$bitmap=New-Object Windows.Media.Imaging.RenderTargetBitmap($width,$height,96,96,[Windows.Media.PixelFormats]::Pbgra32);$bitmap.Render($View);$stride=$width*4;$pixels=New-Object byte[] ($stride*$height);$bitmap.CopyPixels($pixels,$stride,0);$visible=0;$red=0;$blue=0;$edge=0;for($y=0;$y-lt$height;$y++){for($x=0;$x-lt$width;$x++){$o=($y*$stride)+($x*4);$b=[int]$pixels[$o];$g=[int]$pixels[$o+1];$r=[int]$pixels[$o+2];$a=[int]$pixels[$o+3];if($a-le12){continue};$visible++;if($r-gt($b+25)-and$r-gt($g+18)){$red++};if($b-gt($r+25)-and$b-gt($g+18)){$blue++};if($x-lt2-or$y-lt2-or$x-ge($width-2)-or$y-ge($height-2)){$edge++}}};if($visible-lt500){throw "$Label rendered only $visible visible pixels."};if($red-lt40-or$blue-lt40){throw "$Label lost the embedded texture (red=$red blue=$blue visible=$visible)."};Write-Host ($Label+' visiblePixels='+$visible+' redPixels='+$red+' bluePixels='+$blue+' edgePixels='+$edge);[pscustomobject]@{Visible=$visible;Red=$red;Blue=$blue;Edge=$edge}}
Add-Type -Path $binary;$temp=Join-Path ([IO.Path]::GetTempPath()) ('hc-v5-staged-'+[guid]::NewGuid().ToString('N')+'.glb');try{New-HcTexturedProbeGlb $temp;$shelf=New-Object HuymaierConsole.Modeling.LiveModelView -ArgumentList @($temp);if([bool]$shelf.CardMode-or[int]$shelf.GeometryCount-ne1-or[int]$shelf.VertexCount-ne4){throw 'Staged V5 textured shelf did not expose expected geometry/full mode.'};$shelf.SetScalePercent(84);$before=Get-HcStagedRenderStats $shelf 'stagedTexturedShelfLive3D';if([int]$before.Edge-gt0){throw "Staged V5 safe framing touched viewport edge before rotation: $($before.Edge)"};$yaw=[double]$shelf.Yaw;$shelf.Rotate(35,0);$after=Get-HcStagedRenderStats $shelf 'stagedTexturedShelfLive3DRotated';if([math]::Abs([double]$shelf.Yaw-$yaw)-lt20){throw 'Staged V5 textured shelf rotation failed.'};if([int]$after.Edge-gt0){throw "Staged V5 safe framing touched/clipped viewport edge after rotation: $($after.Edge)"}}finally{Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue}

